// Valida e extrai payload do Obsidian Local REST API
// O plugin envia: { vault, path, content }
const body = $input.first().json.body || $input.first().json;

if (!body.path || !body.content) {
  throw new Error('Payload inválido: campos path e content são obrigatórios.');
}

// Extrai frontmatter YAML
const frontmatterMatch = body.content.match(/^---\n([\s\S]*?)\n---/);
let frontmatter = {};
if (frontmatterMatch) {
  for (const line of frontmatterMatch[1].split('\n')) {
    const [k, ...rest] = line.split(':');
    if (k && rest.length) frontmatter[k.trim()] = rest.join(':').trim().replace(/^"|"$/g, '');
  }
}

// Remove frontmatter do conteúdo
const bodyWithoutFm = body.content.replace(/^---\n[\s\S]*?\n---\n?/, '').trim();

// Extrai título (primeiro H1 ou nome do arquivo)
const h1Match = bodyWithoutFm.match(/^# (.+)$/m);
const fileName = body.path.split('/').pop().replace('.md', '');
const title = h1Match ? h1Match[1] : fileName;

// Remove o H1 do corpo
const bodyText = bodyWithoutFm.replace(/^# .+\n?/, '').trim();

return [{
  json: {
    notionId:   frontmatter.notion_id || null,
    title,
    bodyText,
    filePath:   body.path,
    vault:      body.vault || '',
    frontmatter
  }
}];

// Converte Markdown em blocos do Notion
const text = $json.bodyText;
const blocks = [];

for (const rawLine of text.split('\n')) {
  const line = rawLine.trimEnd();

  if (!line) {
    // Parágrafo vazio
    blocks.push({ object: 'block', type: 'paragraph', paragraph: { rich_text: [] } });
    continue;
  }

  function mkText(content) {
    return [{ type: 'text', text: { content } }];
  }

  if (/^### (.+)/.test(line)) {
    blocks.push({ object: 'block', type: 'heading_3', heading_3: { rich_text: mkText(line.replace(/^### /, '')) } });
  } else if (/^## (.+)/.test(line)) {
    blocks.push({ object: 'block', type: 'heading_2', heading_2: { rich_text: mkText(line.replace(/^## /, '')) } });
  } else if (/^# (.+)/.test(line)) {
    blocks.push({ object: 'block', type: 'heading_1', heading_1: { rich_text: mkText(line.replace(/^# /, '')) } });
  } else if (/^- \[x\] (.+)/i.test(line)) {
    blocks.push({ object: 'block', type: 'to_do', to_do: { rich_text: mkText(line.replace(/^- \[x\] /i, '')), checked: true } });
  } else if (/^- \[ \] (.+)/.test(line)) {
    blocks.push({ object: 'block', type: 'to_do', to_do: { rich_text: mkText(line.replace(/^- \[ \] /, '')), checked: false } });
  } else if (/^- (.+)/.test(line)) {
    blocks.push({ object: 'block', type: 'bulleted_list_item', bulleted_list_item: { rich_text: mkText(line.replace(/^- /, '')) } });
  } else if (/^\d+\. (.+)/.test(line)) {
    blocks.push({ object: 'block', type: 'numbered_list_item', numbered_list_item: { rich_text: mkText(line.replace(/^\d+\. /, '')) } });
  } else if (/^> (.+)/.test(line)) {
    blocks.push({ object: 'block', type: 'quote', quote: { rich_text: mkText(line.replace(/^> /, '')) } });
  } else if (/^---$/.test(line)) {
    blocks.push({ object: 'block', type: 'divider', divider: {} });
  } else {
    blocks.push({ object: 'block', type: 'paragraph', paragraph: { rich_text: mkText(line) } });
  }
}

// Notion limita a 100 blocos por chamada
const chunks = [];
for (let i = 0; i < blocks.length; i += 100) {
  chunks.push(blocks.slice(i, i + 100));
}

return [{ json: { ...$json, blocks, chunks } }];

// Após criar página nova, grava o notion_id de volta no frontmatter do Obsidian
const notionId  = $('Criar página no Notion').first().json.id;
const filePath  = $('Parsear Markdown').first().json.filePath;
const origContent = $('Webhook Obsidian').first().json.body?.content
                  || $('Webhook Obsidian').first().json.content || '';

const notionUrl = `https://notion.so/${notionId.replace(/-/g, '')}`;

let updated;
if (/^---/.test(origContent)) {
  updated = origContent
    .replace(/^---\n/, `---\nnotion_id: "${notionId}"\nnotion_url: "${notionUrl}"\n`)
    .replace(/notion_id: .+\n?/, `notion_id: "${notionId}"\n`)
    .replace(/notion_url: .+\n?/, `notion_url: "${notionUrl}"\n`);
} else {
  updated = `---\nnotion_id: "${notionId}"\nnotion_url: "${notionUrl}"\n---\n\n${origContent}`;
}

return [{ json: { notionId, filePath, updatedContent: updated } }];
